contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(this)); }

    function testFuzz_property(uint256 priorCalls) public {

        uint256 n = bound(priorCalls, 0, 10);

        for (uint256 i = 0; i < n; i++) {
            try c.endConfiguration() {
            } catch {
            }
        }

        bool ok;
        try c.endConfiguration() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.configured() == true);
    }
}
